import React, { useEffect, useRef, useState } from "react";
import FileUploadIcon from "@mui/icons-material/FileUpload";
import http, { uploadImage } from "../../services/utility";
import { apisPath, paths } from "../../utils/path";
import { useNavigate } from "react-router-dom";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import { useDispatch } from "react-redux";
import {
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  Button,
} from "@mui/material";

export default function Brands() {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const newBrandRef = useRef(null);
  const [brandName, setBrandName] = useState("");
  const [brandImage, setBrandImage] = useState(null);
  const [cardData, setCardData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [id, setId] = useState(null);

  // Modal state
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [brandToDelete, setBrandToDelete] = useState(null);

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    setLoading(true);
    await http
      .get(apisPath?.admin?.brands)
      .then(async (res) => {
        setCardData(res?.data?.brands);
        setLoading(false);
      })
      .catch((err) => {
        console.log(err);
        setLoading(false);
      });
  };

  const updateData = async (image, id, name) => {
    setBrandImage(image);
    setBrandName(name);
    setId(id);
  };

  const openDeleteModal = (brand) => {
    setBrandToDelete(brand);
    setDeleteModalOpen(true);
  };

  const handleCloseDeleteModal = () => {
    setDeleteModalOpen(false);
    setBrandToDelete(null);
  };

  const confirmDelete = async () => {
    if (!brandToDelete) return;

    await http
      .delete(`${apisPath?.admin?.brands}/${brandToDelete.id}`)
      .then(async (res) => {
        // console.log(res?.data?.message);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
        handleCloseDeleteModal();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
        handleCloseDeleteModal();
      });
  };

  return (
    <div className="brands">
      <div className="brands__heading">
        <h3 className="brands__heading_text page_heading">Brands</h3>
        <button
          className="button-red"
          onClick={() =>
            navigate(
              `/${paths?.front?.user?.products}/${paths?.front?.user?.add_new_brand}`
            )
          }
        >
          Add New Brand
        </button>
      </div>
      <div className="brands__content">
        <div className="brands__content__brands_list">
          <div className="brands__content__brands_list__content">
            {loading ? (
              <div className="loading_progress">
                <div className="loading_spinner"></div>
                <p>Loading brands...</p>
              </div>
            ) : cardData.length > 0 ? (
              cardData?.map((data, index) => {
                return (
                  <BrandCard
                    key={index}
                    data={data}
                    image={data?.image}
                    name={data?.name}
                    deleteData={() => openDeleteModal(data)}
                    updateData={() =>
                      updateData(data?.image, data?.id, data?.name)
                    }
                    id={data?.id}
                  />
                );
              })
            ) : (
              <div className="no_data_found">No Data Found</div>
            )}
          </div>
        </div>
      </div>

      {/* Delete Confirmation Modal */}
      <Dialog
        open={deleteModalOpen}
        onClose={handleCloseDeleteModal}
        aria-labelledby="delete-dialog-title"
        aria-describedby="delete-dialog-description"
        className="brands__delete_modal"
        disablePortal={false}
        container={document.body}
        style={{
          position: 'fixed',
          zIndex: 9999999,
        }}
        BackdropProps={{
          style: {
            position: 'fixed',
            zIndex: 9999998,
          },
        }}
      >
        <DialogTitle id="delete-dialog-title">Delete Brand</DialogTitle>
        <DialogContent>
          <div className="delete-icon-container">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M19 7L18.1327 19.1425C18.0579 20.1891 17.187 21 16.1378 21H7.86224C6.81296 21 5.94208 20.1891 5.86732 19.1425L5 7M10 11V17M14 11V17M15 7V4C15 3.44772 14.5523 3 14 3H10C9.44772 3 9 3.44772 9 4V7M4 7H20" stroke="#dc2626" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          </div>
          <DialogContentText id="delete-dialog-description">
            Are you sure you want to delete <strong>"{brandToDelete?.name}"</strong>?
          </DialogContentText>
          <DialogContentText>
            This action cannot be undone. All associated data will be permanently removed.
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDeleteModal} variant="outlined" className="cancel-btn">
            Cancel
          </Button>
          <Button onClick={confirmDelete} variant="contained" className="delete-btn">
            Delete Brand
          </Button>
        </DialogActions>
      </Dialog>
    </div>
  );
}

const BrandCard = ({ image, name, deleteData, updateData, id, data }) => {
  const navigate = useNavigate();

  return (
    <div className="brands_list_card">
      <div className="brands_list_card__content">
        <img src={image} alt={name} />
      </div>
      <button className="button-red" onClick={deleteData}>
        Delete
      </button>
      <button
        className="button-border-red"
        onClick={() => {
          navigate(
            `/${paths?.front?.user?.products}/${paths?.front?.user?.add_new_brand}`,
            {
              state: { data: data },
            }
          );
        }}
      >
        Update
      </button>
    </div>
  );
};
